const __pageData = JSON.parse('{"title":"Hamas","description":"","frontmatter":{"title":"Hamas","created":"2026-08-06T00:00:00.000Z","updated":"2026-08-06T00:00:00.000Z","type":"entity","tags":["gaza","israel","palestine","october-7"],"sources":["raw/badlands-brief-05f.md","raw/badlands-brief-9eb.md","raw/badlands-news-brief-023.md","raw/badlands-news-brief-079.md","raw/badlands-news-brief-08a.md","raw/badlands-news-brief-071.md","raw/badlands-news-brief-051.md","raw/badlands-news-brief-09d.md","raw/badlands-news-brief-0c1.md","raw/badlands-news-brief-0f0.md","raw/badlands-news-brief-099.md","raw/badlands-news-brief-0db.md","raw/badlands-news-brief-116.md","raw/badlands-news-brief-153.md","raw/badlands-news-brief-143.md","raw/badlands-news-brief-1c8.md","raw/badlands-news-brief-1d1.md","raw/badlands-news-brief-201.md","raw/badlands-news-brief-1ed.md","raw/badlands-news-brief-204.md","raw/badlands-news-brief-264.md","raw/badlands-news-brief-351.md","raw/badlands-news-brief-363.md","raw/badlands-news-brief-362.md","raw/badlands-news-brief-378.md","raw/badlands-news-brief-357.md","raw/badlands-news-brief-52f.md","raw/badlands-news-brief-6b1.md","raw/badlands-news-brief-6bf.md","raw/badlands-news-brief-69b.md","raw/badlands-news-brief-669.md","raw/badlands-news-brief-73f.md","raw/badlands-news-brief-762.md","raw/badlands-news-brief-7c6.md","raw/badlands-news-brief-810.md","raw/badlands-news-brief-7ed.md","raw/badlands-news-brief-855.md"],"confidence":"medium"},"headers":[],"relativePath":"entities/hamas.md","filePath":"entities/hamas.md","lastUpdated":null}');
